C1=R/'reading/french/c1/passages.jsonl'; C2=R/'reading/french/c2/passages.jsonl'; SCHEMA=R/'reading/schema/passage.schema.json'
LOCK=R/'reading/audit/french_c2_unit09_frontier_lock.json'; PLAN=R/'reading/audit/french_c2_unit10_plan.json'; SEL=R/'reading/audit/french_c2_unit10_target_selection.json'
USE={
'technologie':'La « technologie » désigne ici un ensemble d’outils, de pratiques et d’infrastructures; l’analyse sépare ce que le dispositif permet de faire de la décision de l’utiliser dans un contexte précis.',
'donnée':'Une « donnée » est un élément enregistré ou construit pour représenter une observation. Sa présence ne garantit ni sa pertinence ni l’interprétation qu’on lui attribue.',
'réseau':'Un « réseau » relie des acteurs ou des composants. Une relation locale peut donc produire des effets ailleurs, mais la simple connexion ne prouve pas une causalité suffisante.',
'outil':'Un « outil » aide à accomplir une tâche selon une conception particulière. Son évaluation porte sur l’usage, les erreurs, les alternatives et les personnes qui restent responsables de la décision.',
'limite':'Une « limite » indique où une méthode, une mesure ou une conclusion cesse d’être suffisamment soutenue. L’annoncer augmente la précision au lieu d’affaiblir automatiquement l’argument.',
'calcul':'Un « calcul » transforme des valeurs selon des règles définies. Le résultat peut être exact relativement aux entrées et rester inadéquat si la question a été mal formulée.',
'précis':'Un résultat « précis » est formulé ou mesuré avec une faible ambiguïté; précision et validité doivent cependant être distinguées.',
'estimer':'« Estimer » consiste à produire une valeur ou un jugement approximatif à partir d’informations disponibles; l’incertitude de l’estimation doit rester visible.',
'objectif':'Un « objectif » est le résultat que l’action cherche à atteindre. Deux sources peuvent être d’accord sur les faits et diverger parce qu’elles privilégient des objectifs différents.',
'principe':'Un « principe » est une règle ou une base de décision qui aide à traiter plusieurs cas; il doit être appliqué avec ses conditions plutôt que comme une formule indépendante du contexte.',
'surveillance':'La « surveillance » est une observation organisée et répétée. Son évaluation dépend de la finalité, de la durée, de l’accès aux informations et des possibilités de contestation.',
'autoriser':'« Autoriser » signifie permettre un usage sous certaines règles. Une autorisation peut être limitée, révisable et distincte d’une approbation générale de toutes les extensions futures.',
'condition':'Une « condition » précise ce qui doit être vrai pour qu’une conclusion ou une permission reste valable. La supprimer peut transformer une recommandation prudente en affirmation excessive.',
'conscient':'Être « conscient » d’une conséquence signifie en reconnaître l’existence ou l’importance. La conscience d’un risque n’établit pas encore que le compromis choisi est acceptable.',
'priorité':'Une « priorité » indique quel objectif reçoit davantage de poids lorsqu’il faut arbitrer. La rendre explicite permet de distinguer divergence factuelle et divergence normative.',
'appareil':'Un « appareil » est un dispositif conçu pour une fonction. Dans le dossier, son comportement est évalué avec les infrastructures et personnes dont il dépend.',
'électrique':'« Électrique » qualifie une dépendance à l’énergie ou à un circuit; cette dépendance peut créer des contraintes de continuité qui ne sont pas visibles dans la seule interface.',
'micro':'« Micro » désigne ici un microphone ou un petit dispositif informatique selon le contexte; la précision du référent évite de transformer une abréviation en information ambiguë.',
'développer':'« Développer » signifie construire et faire évoluer une solution. Le développement inclut ici les essais, les corrections et la documentation des limites, pas seulement la production initiale.',
'conseiller':'« Conseiller » consiste à proposer une option ou un jugement sans nécessairement détenir le pouvoir final de décision. Une recommandation utile indique les raisons et les incertitudes.',
'récemment':'« Récemment » situe un fait dans un passé proche sans donner seul une chronologie suffisante. Une synthèse exige une date ou une relation temporelle plus précise lorsque l’ordre importe.',
'théorie':'Une « théorie » organise des relations explicatives entre observations. Elle doit être distinguée d’un simple résumé des faits et rester ouverte aux observations qui la mettraient en difficulté.',
'info':'« Info » est une forme abrégée d’information ou d’informatique selon le contexte. Le lecteur doit résoudre ce sens par la fonction du passage plutôt que par la forme isolée.',
'mondial':'« Mondial » décrit une portée à l’échelle du monde; un cas local ne devient pas mondial simplement parce qu’il circule largement en ligne.',
'recommander':'« Recommander » consiste à privilégier une option sur la base de critères et d’informations. Une recommandation de synthèse doit indiquer pour qui, dans quelles conditions et avec quelle possibilité de révision.'}
EXTRA=[
"Une lecture rivale est ensuite construite avec les mêmes informations mais une priorité différente. Le lecteur doit montrer exactement quelle prémisse normative change et quelles conséquences restent factuelles. Cette opération évite de traiter tout désaccord comme une erreur de données et oblige à identifier l’endroit précis où les raisonnements se séparent.",
"Le dossier ajoute un test de provenance. Deux résumés peuvent sembler indépendants alors qu’ils dérivent de la même source initiale. Le lecteur trace donc la chaîne d’information avant de compter les confirmations et distingue reproduction, interprétation, observation nouvelle et simple reformulation.",
"Une autre tâche change l’échelle d’analyse. Un dispositif peut améliorer un résultat individuel tout en augmentant une dépendance collective, ou coûter davantage au système tout en protégeant un groupe particulièrement exposé. La synthèse doit annoncer l’unité à laquelle elle mesure bénéfice et dommage avant de comparer les options.",
"Le lecteur construit aussi une chronologie minimale. Une affirmation récente, une estimation plus ancienne et une réaction ultérieure ne doivent pas être fusionnées comme si elles avaient été produites simultanément. L’ordre temporel peut transformer une corrélation en réaction plausible ou révéler qu’une explication supposée apparaît après le fait qu’elle prétend expliquer.",
"Le contreargument final porte sur la réversibilité. Une option peut sembler légèrement moins performante mais être beaucoup plus facile à corriger si une hypothèse tombe. Dans un contexte d’incertitude, cette propriété peut légitimement recevoir un poids distinct de la performance moyenne, à condition que le coût de retour en arrière soit lui-même décrit.",
"Enfin, la conclusion est reformulée à trois niveaux : ce qui est directement établi, ce qui est l’explication la mieux soutenue parmi celles examinées et ce qui reste une hypothèse ouverte. Cette hiérarchie empêche une synthèse fluide de masquer les différences de force probante entre ses composantes.",
"Le dossier exige ensuite une objection capable de changer la recommandation. Une objection purement décorative ne suffit pas : elle doit identifier une information plausible, une valeur concurrente ou une limite de portée qui, si elle était confirmée, conduirait à choisir autrement. La position finale devient ainsi révisable plutôt que rhétoriquement protégée.",
"La portée de l’exercice reste volontairement générale. Tous les cas sont fictifs et servent à intégrer des méthodes de lecture, de comparaison et de décision. Le transfert réussi consiste à refaire ces opérations sur un nouveau dossier, non à mémoriser la conclusion particulière d’un scénario."
]
def h(p): return subprocess.check_output(['git','hash-object',str(p)],text=True).strip()
def fit(ps,lo,hi):
 out=list(ps); text='\n\n'.join(out); i=0
 while len(text.split())<lo and i<len(EXTRA): out[-1]+=' '+EXTRA[i]; i+=1; text='\n\n'.join(out)
 if not lo<=len(text.split())<=hi: raise AssertionError(f'C2 Unit10 word band {len(text.split())} not {lo}-{hi}')
 return out,text
def bridge(fs): return 'Révision croisée : '+', '.join(f'« {x} »' for x in fs)+'. Ces formes du dossier précédent sont reprises pour relier test, incertitude, justice, panne et scénarios à une synthèse multi-source.'
def qitems(s,forms):
 core=[('main_claim',s['qclaim'],s['aclaim'],[forms[0]]),('ambiguity_resolution',s['qamb'],s['aamb'],[forms[1]]),('assumption',s['qassume'],s['aassume'],[forms[2]]),('rhetorical_function',s['qrhet'],s['arhet'],[forms[3]]),('stance',s['qstance'],s['astance'],[forms[4]])]
 return core+[('vocabulary_in_context',f'Quel rôle analytique joue « {f} » ?',USE[f],[f]) for f in forms]
def make(s,forms,reviews,prior,D,lo,hi,theme):
 ps=list(s['paras']); ps[1]+=' '+' '.join(USE[f] for f in forms); ps[2]+=' '+bridge(reviews); ps,text=fit(ps,lo,hi); P=base.prior(prior); new=[c2base.nt(f,text,D) for f in forms]; rev=[base.rev(f,P) for f in reviews]; ids={t['form']:t['id'] for t in new+rev}; q,a=base.qa(qitems(s,forms),ids)
 return {'id':s['id'],'language':'fr','cefr':'C2','unit':10,'sequence':s['seq'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':['educational','public','professional'],'topics':[theme]+s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”\"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':rev,'grammar_targets':[{'id':s['id']+'-g1','role':'integration','description':'integrate source attribution, modality, concession, temporal qualification and conditional recommendations'}],'discourse_targets':[{'id':s['id']+'-d1','role':'integration','description':'synthesize multiple sources, distinguish fact from value, compare rival explanations and state revision conditions'}],'questions':q,'answer_key':a,'speed_training':{'timed':False,'benchmark_eligible':False,'comprehension_gate':0.8,'new_word_policy':'controlled','notes':'C2 Unit10 capstone synthesis.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['All source-like materials and cases are original fictional constructions.']},'paired_text_group':s.get('pair'),'prerequisites':['French C2 Unit09'],'difficulty_notes_internal':'C2 capstone multi-source synthesis, paired-text reconciliation and revision.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_c2_u10']}
